def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    def opp_c_ratio(start):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if opp[i] == 'C':
                cnt += 1
        return cnt / tot if tot else 0.0

    recent_len = min(10, n)
    recent = opp[n-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    total_c = sum(1 for a in opp if a == 'C')
    total_ratio = total_c / n

    # Detect likely randomness/always-defect
    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            # Grudge, but avoid total collapse
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if all(a == 'C' for a in last6):
            return 'C'

    # Tit-for-tat with forgiveness and probing
    if n >= 2:
        if opp[-1] == 'D' and me[-1] == 'C':
            # We were just defected on
            if recent_ratio > 0.6:
                # Forgive to keep cooperation
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
        if opp[-1] == 'D' and me[-1] == 'D':
            # Mutual defection: attempt to break out
            if n % 7 == 0 or recent_ratio > 0.35:
                return 'C'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if opp[-1] == 'C':
            # Reward cooperation, punish exploitation pattern
            if len(history) >= 3:
                last3 = opp[-3:]
                if last3 == ['C', 'C', 'D'] and me[-1] == 'C':
                    return 'D'
            return 'C'

    return 'C'
